        return km.getKeyModifier().isActive((IKeyConflictContext)(keyConflictContext == 0 ? KeyConflictContext.GUI : (keyConflictContext == 1 ? KeyConflictContext.IN_GAME : KeyConflictContext.UNIVERSAL)));
    }
}

